mapper.select:
SELECT u.id, u.name, u.email, u.phone, u.gender, u.role, u.status, u.created_at AS createdAt, COALESCE(doc.cnt, 0) AS noteCount, COALESCE(kb.cnt, 0) AS kbCount FROM user u LEFT JOIN ( SELECT creator_id, COUNT(*) AS cnt FROM document WHERE deleted_at IS NULL GROUP BY creator_id ) doc ON u.id = doc.creator_id LEFT JOIN ( SELECT creator_id, COUNT(*) AS cnt FROM knowledge_base WHERE deleted = 0 GROUP BY creator_id ) kb ON u.id = kb.creator_id
AND (u.name LIKE CONCAT('%', #{keyword}, '%') OR u.email LIKE CONCAT('%', #{keyword}, '%') OR u.phone LIKE CONCAT('%', #{keyword}, '%'))
AND u.status = #{status}
AND u.role = #{role}
ORDER BY u.created_at DESC

mapper.update:
UPDATE user
name = #{req.name}, email = #{req.email}, phone = #{req.phone}, gender = #{req.gender}, role = #{req.role}, status = #{req.status}, avatar = #{req.avatar}, bio = #{req.bio},
WHERE id = #{userId}
